//@version=1
// 21-155 Inverse FVG Retest + strong close - NQ 60m - all sessions
// FX Replay (FXR Script) indicator, generated by: python -m confluence.cli fxr-script 21-155
//
// Put it on an NQ 60-minute chart. In the indicator's settings set "Total candles to render"
// to 3000, the most FX Replay allows: the script needs its first 300 bars to settle.
// It marks every setup, simulates the trade the backtest takes (entry, stop, exit) and keeps a
// running tally in R and dollars. Take the marked trades with FX Replay's order tools.
//
// Backtest, Sep 2018 - Sep 2026 on the Nasdaq-100 CFD: 2,890 trades, 33% win rate, +0.06R per trade after costs.
// The script sees bars, not the 1-minute path inside them, so a few exits can differ.
// If anything fails, a red line labelled "SCRIPT ERROR" marks the bar where it happened.
//
// How FX Replay runs a script: it runs everything outside init and onTick again on every bar
// and keeps only top-level variables that start as a number, true/false, text, {object} or
// [array with an item]. So the state below is plain values and arrays (each array starts with
// a placeholder that the first bar clears), all the logic sits inside onTick, and nothing uses
// "new" or the clock, which FX Replay rejects.

init = () => {
  indicator({ onMainPanel: true, format: 'inherit' });
  input.float('Risk per trade ($)', 500, 'fxrRisk', 10, 10000, 10);
  input.float('Point value per contract ($)', 2, 'fxrPointValue', 0.1, 100, 0.1);
  input.float('Round-trip cost (points)', 1.11, 'fxrCost', 0, 20, 0.01);
  input.float('Tick size', 0.25, 'fxrTick', 0.0001, 10, 0.0001);
  input.bool('Take shorts', true, 'fxrShorts');
  input.bool('Draw trades', true, 'fxrDraw');
  input.int('Draw trades from (YYYYMMDD)', 20000101, 'fxrDrawFrom', 19000101, 21001231, 1);
};

// ------------------------------------------------------------------ state kept between bars
let S_FRESH = true;
const S_BT = [0];                // bar open time (ms)
const S_BO = [0];
const S_BH = [0];
const S_BL = [0];
const S_BC = [0];
const S_BDAY = [0];              // trading day, rolls at 18:00 New York
const S_BTDMO = [0];             // minutes since 18:00 New York when the bar opens
const S_BTDMC = [0];             // ... and when it closes
const S_TRNG = [0];              // true range
const S_ATR = [0];               // ATR(14), Wilder
const S_ATRSUM = [0];            // running sum of ATR for its 100-bar average
const S_PIV = [{ p: 0, type: 0 }];    // confirmed swings: type 1 = high, -1 = low
const S_ZZ = { d: 0, hi: -1e300, hiI: 0, lo: 1e300, loI: 0 };
const S_GAP = { bearOk: false, bearTop: 0, bearBot: 0, bearJ: -1, bullOk: false, bullTop: 0, bullBot: 0, bullJ: -1 };
const S_ORD = { open: false, kind: '', dir: 0, px: 0, sig: -1, day: -1, atr: 0, alive: false, until: -1 };
const S_POS = { open: false, dir: 0, entry: 0, stop: 0, stop0: 0, risk: 0, best: 0, fill: -1, sig: -1, day: -1, trailing: false, contracts: 0 };
const S_RUN = { curDay: -1, dayCount: 0, totalR: 0, errorShown: false };
const S_TRADES = [{ dir: 0, t0: 0, entry: 0, stop: 0, t1: 0, exit: 0, r: 0, why: '', contracts: 0 }];
// What the latest bar put on the chart. FX Replay repeats onTick on every tick of the live bar and
// wipes that bar's drawings each time, so they are kept here and drawn again on every tick.
const S_OUT = { t0: 0, longSetup: NaN, shortSetup: NaN, buy: NaN, sell: NaN };
const S_DRAW = [{ kind: 0, t0: 0, p0: 0, t1: 0, p1: 0, txt: '' }];   // kind 0 win, 1 loss, 2 stop, 3 error
// Trades already written to the log. The count sits one level down so the live-bar rollback,
// which copies only the top level, does not undo it, and a trade is not logged twice.
const S_LOGGED = { upTo: { n: 0 } };

onTick = (length, _moment, _, ta, inputs) => {
  // Helpers are declared with "var": FX Replay moves a const/let function out of onTick when it
  // only uses globals, state and other helpers, and there it can no longer see the state.

  // ---------------------------------------------------------------- strategy constants
  const CFG = {
    sid: '21-155',
    tf: 60,                // chart timeframe the rules were tested on (minutes)
    signal: 'ifvgRetest',      // setup detector: 'swingEngulf' or 'ifvgRetest'
    entry: 'market',        // 'market' = next bar open; 'stop' = 1 tick beyond the signal bar, valid 3 bars
    stopAtr: 1.0,      // initial stop = stopAtr x ATR(14) of the signal bar from the entry
    trail: true,          // after +1R, trail 2 x ATR(14) behind the best price at each bar close
    sesFrom: 18 * 60 + 5,      // the signal bar must CLOSE between these New York times (minutes after midnight)
    sesTo: 15 * 60 + 30,
    flatAt: 16 * 60 + 5,          // flat at this New York time
    maxPerDay: 4,
    warmup: 300,               // no setups in the first 300 bars while ATR, swings and averages settle
    atrLen: 14,
    swingAtr: 3.0,             // a swing high/low is confirmed after a 3 x ATR reversal
    minStopAtr: 0.3,           // stops never tighter than 0.3 ATR
    minStopCosts: 4.0          // ... or 4 round-trip costs
  };

  // ---------------------------------------------------------------- settings
  var num = function (v, d) { return typeof v === 'number' && isFinite(v) ? v : d; };
  const IN = {
    riskUsd: num(inputs.fxrRisk, 500),
    pointValue: num(inputs.fxrPointValue, 2),
    costPts: num(inputs.fxrCost, 1.11),
    tick: num(inputs.fxrTick, 0.25),
    shorts: inputs.fxrShorts !== false,
    draw: inputs.fxrDraw !== false,
    drawFrom: num(inputs.fxrDrawFrom, 20000101)
  };

  // ---------------------------------------------------------------- New York clock (calendar arithmetic, no Date)
  const DAY_MS = 86400000;
  var toMs = function (t) { return t < 1e12 ? t * 1000 : t; };
  // days since 1970-01-01 of a calendar date (month 1-12)
  var daysFromCivil = function (y, m, d) {
    const yy = m <= 2 ? y - 1 : y;
    const era = Math.floor(yy / 400);
    const yoe = yy - era * 400;
    const doy = Math.floor((153 * (m > 2 ? m - 3 : m + 9) + 2) / 5) + d - 1;
    const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
    return era * 146097 + doe - 719468;
  };
  // calendar date (YYYYMMDD) of a day count since 1970-01-01
  var civil = function (days) {
    const z = days + 719468;
    const era = Math.floor(z / 146097);
    const doe = z - era * 146097;
    const yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
    const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
    const mp = Math.floor((5 * doy + 2) / 153);
    const d = doy - Math.floor((153 * mp + 2) / 5) + 1;
    const m = mp < 10 ? mp + 3 : mp - 9;
    return (yoe + era * 400 + (m <= 2 ? 1 : 0)) * 10000 + m * 100 + d;
  };
  var nthSunday = function (y, m, n) {        // UTC ms of the n-th Sunday of month m (1-12)
    const first = daysFromCivil(y, m, 1);
    const weekday = (((first + 4) % 7) + 7) % 7;   // 0 = Sunday; 1970-01-01 was a Thursday
    return (first + ((7 - weekday) % 7) + 7 * (n - 1)) * DAY_MS;
  };
  var nyOffsetHours = function (ms) {         // US daylight time: 2nd Sun Mar 07:00 UTC to 1st Sun Nov 06:00 UTC
    const y = Math.floor(civil(Math.floor(ms / DAY_MS)) / 10000);
    const a = nthSunday(y, 3, 2) + 7 * 3600000;
    const b = nthSunday(y, 11, 1) + 6 * 3600000;
    return (ms >= a && ms < b) ? -4 : -5;
  };
  // The trading day rolls at 18:00 New York; "tdm" = minutes since 18:00.
  var tradingDay = function (ms) { return Math.floor((ms + nyOffsetHours(ms) * 3600000 + 6 * 3600000) / DAY_MS); };
  var tradingMinute = function (ms) {
    const local = ms + nyOffsetHours(ms) * 3600000 + 6 * 3600000;
    return Math.floor((((local % DAY_MS) + DAY_MS) % DAY_MS) / 60000);
  };
  var tdmOf = function (minutesAfterMidnight) { return (((minutesAfterMidnight - 18 * 60) % 1440) + 1440) % 1440; };
  var nyDate = function (ms) { return civil(Math.floor((ms + nyOffsetHours(ms) * 3600000) / DAY_MS)); };
  var nyStamp = function (ms) {                // 'YYYY-MM-DD HH:MM' New York
    const local = ms + nyOffsetHours(ms) * 3600000;
    const ymd = civil(Math.floor(local / DAY_MS));
    const mins = Math.floor((((local % DAY_MS) + DAY_MS) % DAY_MS) / 60000);
    var two = function (x) { return (x < 10 ? '0' : '') + x; };
    return Math.floor(ymd / 10000) + '-' + two(Math.floor(ymd / 100) % 100) + '-' + two(ymd % 100) + ' ' +
      two(Math.floor(mins / 60)) + ':' + two(mins % 60);
  };

  var resetState = function () {
    S_BT.length = 0; S_BO.length = 0; S_BH.length = 0; S_BL.length = 0; S_BC.length = 0;
    S_BDAY.length = 0; S_BTDMO.length = 0; S_BTDMC.length = 0;
    S_TRNG.length = 0; S_ATR.length = 0; S_ATRSUM.length = 0; S_PIV.length = 0;
    S_ZZ.d = 0; S_ZZ.hi = -1e300; S_ZZ.hiI = 0; S_ZZ.lo = 1e300; S_ZZ.loI = 0;
    S_GAP.bearOk = false; S_GAP.bullOk = false;
    S_ORD.open = false; S_POS.open = false;
    S_RUN.curDay = -1; S_RUN.dayCount = 0; S_RUN.totalR = 0; S_RUN.errorShown = false;
    S_TRADES.length = 0; S_DRAW.length = 0; S_OUT.t0 = 0; S_LOGGED.upTo.n = 0;
  };

  // ---------------------------------------------------------------- indicators
  var updateIndicators = function (k) {
    const h = S_BH[k], l = S_BL[k];
    let tr = h - l;
    if (k > 0) tr = Math.max(h - l, Math.abs(h - S_BC[k - 1]), Math.abs(l - S_BC[k - 1]));
    S_TRNG[k] = tr;
    const n = CFG.atrLen;
    if (k < n - 1) S_ATR[k] = NaN;
    else if (k === n - 1) {
      let s = 0;
      for (let j = 0; j < n; j++) s += S_TRNG[j];
      S_ATR[k] = s / n;
    } else S_ATR[k] = (S_ATR[k - 1] * (n - 1) + tr) / n;
    // running sum of ATR (NaN counted as 0) for the 100-bar average
    const az = isNaN(S_ATR[k]) ? 0 : S_ATR[k];
    S_ATRSUM[k] = (k > 0 ? S_ATRSUM[k - 1] : 0) + az;
    // zigzag swings, confirmed on the bar where the reversal happens
    const a = S_ATR[k];
    if (a > 0) {
      if (h > S_ZZ.hi) { S_ZZ.hi = h; S_ZZ.hiI = k; }
      if (l < S_ZZ.lo) { S_ZZ.lo = l; S_ZZ.loI = k; }
      if (S_ZZ.d >= 0 && S_ZZ.hi - l >= CFG.swingAtr * a && (S_ZZ.d === 1 || S_ZZ.hiI > S_ZZ.loI)) {
        S_PIV.push({ p: S_ZZ.hi, type: 1 });
        S_ZZ.d = -1; S_ZZ.lo = l; S_ZZ.loI = k;
      } else if (S_ZZ.d <= 0 && h - S_ZZ.lo >= CFG.swingAtr * a && (S_ZZ.d === -1 || S_ZZ.loI > S_ZZ.hiI)) {
        S_PIV.push({ p: S_ZZ.lo, type: -1 });
        S_ZZ.d = 1; S_ZZ.hi = h; S_ZZ.hiI = k;
      }
    }
  };
  var atrAverage100 = function (k) {
    if (k < 99) return NaN;
    return (S_ATRSUM[k] - (k >= 100 ? S_ATRSUM[k - 100] : 0)) / 100;
  };

  // ---------------------------------------------------------------- setups; each returns {up, dn}
  // 36-221: a recent swing low retested as support + bullish engulfing + ATR below its 100-bar average
  var swingEngulf = function (k) {
    const out = { up: false, dn: false };
    if (k < 1) return out;
    const o = S_BO[k], h = S_BH[k], l = S_BL[k], c = S_BC[k], o1 = S_BO[k - 1], c1 = S_BC[k - 1], a = S_ATR[k];
    const calm = S_ATR[k] < atrAverage100(k);
    const engUp = c1 < o1 && c > o && c >= o1 && o <= c1;
    const engDn = c1 > o1 && c < o && c <= o1 && o >= c1;
    let sup = false, res = false, nl = 0, nh = 0;
    if (S_PIV.length >= 2) {
      for (let j = S_PIV.length - 1; j >= 0 && (nl < 4 || nh < 4); j--) {
        const pv = S_PIV[j];
        if (pv.type === -1 && nl < 4) {
          nl++;
          if (pv.p < c && Math.abs(l - pv.p) <= 0.25 * a && c > pv.p) sup = true;
        } else if (pv.type === 1 && nh < 4) {
          nh++;
          if (pv.p > c && Math.abs(h - pv.p) <= 0.25 * a && c < pv.p) res = true;
        }
      }
    }
    out.up = sup && engUp && calm;
    out.dn = res && engDn && calm;
    return out;
  };
  // 21-155: the bar trades into a fair-value gap from the last 20 bars and closes back through it,
  // closes beyond the prior bar's extreme, and closes in the outer 30% of its range
  var ifvgRetest = function (k) {
    const out = { up: false, dn: false };
    if (k < 2) return out;
    const o = S_BO[k], h = S_BH[k], l = S_BL[k], c = S_BC[k];
    const r = Math.max(h - l, 1e-12);
    const bearOk = S_GAP.bearOk && S_GAP.bearJ <= k - 1 && (k - 1) - S_GAP.bearJ <= 20;
    const bullOk = S_GAP.bullOk && S_GAP.bullJ <= k - 1 && (k - 1) - S_GAP.bullJ <= 20;
    out.up = bearOk && l <= S_GAP.bearTop && c > S_GAP.bearBot && c > S_GAP.bearTop && c > S_BH[k - 1] && c > o && (c - l) >= 0.7 * r;
    out.dn = bullOk && h >= S_GAP.bullBot && c < S_GAP.bullTop && c < S_GAP.bullBot && c < S_BL[k - 1] && c < o && (h - c) >= 0.7 * r;
    // remember gaps formed on this bar (usable from the next bar)
    const a = S_ATR[k], h2 = S_BH[k - 2], l2 = S_BL[k - 2];
    if (h < l2 && (l2 - h) > 0.1 * a) { S_GAP.bearOk = true; S_GAP.bearTop = l2; S_GAP.bearBot = h; S_GAP.bearJ = k; }
    if (l > h2 && (l - h2) > 0.1 * a) { S_GAP.bullOk = true; S_GAP.bullTop = l; S_GAP.bullBot = h2; S_GAP.bullJ = k; }
    return out;
  };
  var setupAt = function (k) {
    if (CFG.signal === 'swingEngulf') return swingEngulf(k);
    return ifvgRetest(k);
  };

  // ---------------------------------------------------------------- chart output of this bar
  var fmt = function (x, d) { return (x >= 0 ? '+' : '-') + Math.abs(x).toFixed(d); };
  var money = function (x) {
    let s = String(Math.round(Math.abs(x)));
    let out = '';
    while (s.length > 3) { out = ',' + s.slice(-3) + out; s = s.slice(0, -3); }
    return (x < 0 ? '-$' : '$') + s + out;
  };
  // Marks the bar where something failed with a red vertical line labelled with the message.
  var showError = function (msg) {
    if (S_RUN.errorShown) return;
    S_RUN.errorShown = true;
    console.log(CFG.sid + ' SCRIPT ERROR: ' + msg);
    const k = S_BT.length - 1;
    if (k >= 0) S_DRAW.push({ kind: 3, t0: S_BT[k], p0: S_BH[k], t1: S_BT[k], p1: S_BL[k], txt: CFG.sid + ' SCRIPT ERROR: ' + msg });
  };
  // A green/red line from entry to exit, and the dashed initial stop, which carries the label: it is
  // horizontal, so the text stays readable.
  var drawTrade = function (tr) {
    if (!IN.draw || nyDate(tr.t0) < IN.drawFrom) return;
    S_DRAW.push({ kind: tr.r > 0 ? 0 : 1, t0: tr.t0, p0: tr.entry, t1: tr.t1, p1: tr.exit, txt: '' });
    S_DRAW.push({ kind: 2, t0: tr.t0, p0: tr.stop, t1: tr.t1, p1: tr.stop,
      txt: '#' + S_TRADES.length + ' ' + nyStamp(tr.t0).slice(0, 10) + ' ' + (tr.dir > 0 ? 'long' : 'short') + ' ' +
        fmt(tr.r, 2) + 'R | total ' + fmt(S_RUN.totalR, 1) + 'R = ' + money(S_RUN.totalR * IN.riskUsd) });
  };
  // Every closed trade also goes to the editor's log as a CSV row, to copy out and check.
  var logTrade = function (tr) {
    if (S_TRADES.length <= S_LOGGED.upTo.n) return;
    S_LOGGED.upTo.n = S_TRADES.length;
    if (S_TRADES.length === 1) console.log('strategy,trade,entry_time_ny,side,entry,stop,exit_time_ny,exit,exit_reason,net_r,total_r');
    console.log([CFG.sid, S_TRADES.length, nyStamp(tr.t0), tr.dir > 0 ? 'long' : 'short', tr.entry.toFixed(2), tr.stop.toFixed(2),
      nyStamp(tr.t1), tr.exit.toFixed(2), tr.why, tr.r.toFixed(3), S_RUN.totalR.toFixed(2)].join(','));
  };

  // ---------------------------------------------------------------- the trade simulation
  var exitTdm = function () { return tdmOf(CFG.flatAt); };
  var closeTrade = function (xp, k, why) {
    const r = ((xp - S_POS.entry) * S_POS.dir) / S_POS.risk - IN.costPts / S_POS.risk;
    const tr = { dir: S_POS.dir, t0: S_BT[S_POS.fill], entry: S_POS.entry, stop: S_POS.stop0, t1: S_BT[k], exit: xp, r: r,
                 why: why, contracts: S_POS.contracts };
    S_TRADES.push(tr);
    S_RUN.totalR += r;
    S_POS.open = false;
    drawTrade(tr);
    logTrade(tr);
  };
  var openTrade = function (k, entry) {
    const a = S_ORD.atr, dir = S_ORD.dir;
    let stop = entry - dir * CFG.stopAtr * a;
    let risk = (entry - stop) * dir;
    const floor = Math.max(CFG.minStopAtr * a, CFG.minStopCosts * IN.costPts);
    if (!(risk >= floor)) { risk = floor; stop = entry - dir * risk; }
    S_POS.open = true; S_POS.dir = dir; S_POS.entry = entry; S_POS.stop = stop; S_POS.stop0 = stop; S_POS.risk = risk;
    S_POS.best = entry; S_POS.fill = k; S_POS.sig = S_ORD.sig; S_POS.day = S_ORD.day; S_POS.trailing = false;
    S_POS.contracts = Math.max(1, Math.round(IN.riskUsd / (risk * IN.pointValue)));
    S_ORD.open = false;
    if (S_ORD.day !== S_RUN.curDay) { S_RUN.curDay = S_ORD.day; S_RUN.dayCount = 0; }
    S_RUN.dayCount++;
    if (IN.draw) { if (dir > 0) S_OUT.buy = entry; else S_OUT.sell = entry; }
  };
  // One bar of an open position; returns true if the trade closed in this bar.
  var manage = function (k, fillBar) {
    const o = S_BO[k], h = S_BH[k], l = S_BL[k];
    if (S_BDAY[k] !== S_POS.day) { closeTrade(S_BC[k - 1], k - 1, 'day'); return true; }
    const ex = exitTdm();
    if (S_BTDMO[k] >= ex || (S_BTDMO[k] < ex && S_BTDMC[k] > ex)) { closeTrade(o, k, 'session'); return true; }
    const sameAsFill = fillBar && CFG.entry !== 'market';
    // On the bar a stop order fills, the bar's other extreme may have come before the fill.
    // Assume the usual path: a green bar goes open-low-high-close, a red bar open-high-low-close.
    const beforeFill = sameAsFill && (S_POS.dir > 0 ? S_BC[k] >= o : S_BC[k] <= o);
    if (!beforeFill) {
      if (S_POS.dir > 0 && l <= S_POS.stop) { closeTrade((sameAsFill || o > S_POS.stop) ? S_POS.stop : o, k, S_POS.trailing ? 'trail' : 'stop'); return true; }
      if (S_POS.dir < 0 && h >= S_POS.stop) { closeTrade((sameAsFill || o < S_POS.stop) ? S_POS.stop : o, k, S_POS.trailing ? 'trail' : 'stop'); return true; }
    }
    S_POS.best = S_POS.dir > 0 ? Math.max(S_POS.best, h) : Math.min(S_POS.best, l);
    if (!beforeFill && CFG.trail && (S_POS.best - S_POS.entry) * S_POS.dir >= S_POS.risk && S_ATR[k] > 0) {
      const ns = S_POS.best - S_POS.dir * 2 * S_ATR[k];
      if ((ns - S_POS.stop) * S_POS.dir > 0) { S_POS.stop = ns; S_POS.trailing = true; }
    }
    return false;
  };

  var onBar = function (k) {
    updateIndicators(k);
    const sg = setupAt(k);                              // always run: it also tracks gaps
    const goLong = sg.up && k >= CFG.warmup;
    const goShort = sg.dn && IN.shorts && k >= CFG.warmup;
    let evaluate = true;
    if (S_ORD.open) {
      if (S_ORD.kind === 'market') {
        S_ORD.open = false;
        if (S_BDAY[k] === S_ORD.day && S_BTDMO[k] < exitTdm()) {
          openTrade(k, S_BO[k]);
          if (!manage(k, true)) evaluate = false;
        }
      } else {
        if (S_ORD.alive && (S_BDAY[k] !== S_ORD.day || S_BTDMO[k] >= exitTdm())) S_ORD.alive = false;
        const hit = S_ORD.dir > 0 ? S_BH[k] >= S_ORD.px : S_BL[k] <= S_ORD.px;
        if (S_ORD.alive && hit) {
          const entry = S_ORD.dir > 0 ? Math.max(S_BO[k], S_ORD.px) : Math.min(S_BO[k], S_ORD.px);
          openTrade(k, entry);
          if (!manage(k, true)) evaluate = false;
        } else if (k >= S_ORD.until) {
          S_ORD.open = false;
        } else {
          evaluate = false;
        }
      }
    } else if (S_POS.open) {
      if (!manage(k, false)) evaluate = false;
    }
    if (!evaluate || S_POS.open || S_ORD.open) return;
    // a new setup on this bar's close
    if (goLong === goShort) return;
    const tc = S_BTDMC[k];
    if (tc < tdmOf(CFG.sesFrom) || tc > tdmOf(CFG.sesTo)) return;
    if (S_BDAY[k] === S_RUN.curDay && S_RUN.dayCount >= CFG.maxPerDay) return;
    if (!(S_ATR[k] > 0)) return;
    const dir = goLong ? 1 : -1;
    S_ORD.open = true; S_ORD.kind = CFG.entry; S_ORD.dir = dir; S_ORD.sig = k; S_ORD.day = S_BDAY[k]; S_ORD.atr = S_ATR[k];
    S_ORD.alive = true; S_ORD.until = k + 3;
    S_ORD.px = dir > 0 ? S_BH[k] + IN.tick : S_BL[k] - IN.tick;
    if (IN.draw) { if (dir > 0) S_OUT.longSetup = S_BC[k]; else S_OUT.shortSetup = S_BC[k]; }
  };

  // ---------------------------------------------------------------- bar feed
  // The bar before the current one is complete: process it once, when the current bar appears.
  const now = time(0);
  try {
    const t1 = time(1);
    const o = openC(1), h = high(1), l = low(1), c = closeC(1);
    if (t1 > 0 && now > t1 && !isNaN(o) && !isNaN(h) && !isNaN(l) && !isNaN(c)) {
      const t = toMs(t1);
      if (S_FRESH) { resetState(); S_FRESH = false; }
      if (S_BT.length > 0 && t < S_BT[S_BT.length - 1]) resetState();     // the replay went back: start over
      if (S_BT.length === 0 || t > S_BT[S_BT.length - 1]) {
        S_OUT.t0 = now; S_OUT.longSetup = NaN; S_OUT.shortSetup = NaN; S_OUT.buy = NaN; S_OUT.sell = NaN;
        S_DRAW.length = 0;
        const tdm = tradingMinute(t);
        S_BT.push(t); S_BO.push(o); S_BH.push(h); S_BL.push(l); S_BC.push(c);
        S_BDAY.push(tradingDay(t)); S_BTDMO.push(tdm); S_BTDMC.push(Math.min(tdm + CFG.tf, 1440));
        onBar(S_BT.length - 1);
      }
    }
  } catch (e) {
    showError(String(e));
  }

  // ---------------------------------------------------------------- draw what this bar produced
  if (S_OUT.t0 === now) {
    const mk = { ls: S_OUT.longSetup, ss: S_OUT.shortSetup, buy: S_OUT.buy, sell: S_OUT.sell };
    if (!isNaN(mk.ls)) plot.shapes('Long setup', mk.ls, 'setup', 'rgba(38, 166, 91, 0.95)', '#FFFFFF', 'shape_triangle_up', 'BelowBar', 'tiny', -1, 0, 'long_setup');
    if (!isNaN(mk.ss)) plot.shapes('Short setup', mk.ss, 'setup', 'rgba(235, 64, 52, 0.95)', '#FFFFFF', 'shape_triangle_down', 'AboveBar', 'tiny', -1, 0, 'short_setup');
    if (!isNaN(mk.buy)) plot.shapes('Buy', mk.buy, 'BUY', 'rgba(38, 166, 91, 0.95)', '#FFFFFF', 'shape_arrow_up', 'BelowBar', 'small', -1, 0, 'buy_fill');
    if (!isNaN(mk.sell)) plot.shapes('Sell', mk.sell, 'SELL', 'rgba(235, 64, 52, 0.95)', '#FFFFFF', 'shape_arrow_down', 'AboveBar', 'small', -1, 0, 'sell_fill');
    for (let i = 0; i < S_DRAW.length; i++) {
      const d = S_DRAW[i];
      try {
        if (d.kind === 2) {
          trendLine(newPoint(d.t0, d.p0), newPoint(d.t1, d.p1),
            { linecolor: color.rgba(235, 64, 52, 0.6), linewidth: 1, linestyle: 2, showLabel: true }, d.txt);
        } else if (d.kind === 3) {
          trendLine(newPoint(d.t0, d.p0), newPoint(d.t1, d.p1), { linecolor: color.rgba(235, 64, 52, 0.95), linewidth: 3, showLabel: true }, d.txt);
        } else {
          trendLine(newPoint(d.t0, d.p0), newPoint(d.t1, d.p1),
            { linecolor: d.kind === 0 ? color.rgba(38, 166, 91, 0.95) : color.rgba(235, 64, 52, 0.95), linewidth: 2 });
        }
      } catch (e) {
        // a drawing that fails must not stop the rest
      }
    }
  }
};
